BEGIN;
SELECT no_plan();
SELECT ok(NOT has_table_privilege('authenticated','payroll.payment_requests','SELECT'),'request payload has no direct client read');
SELECT ok(NOT has_table_privilege('service_role','payroll.payment_requests','UPDATE'),'request has no direct service write bypass');
SELECT set_config('test.request',jsonb_build_object('expected',(SELECT revision FROM payroll.payment_heads WHERE tenant_id=current_setting('test.tenant')::uuid AND output_id=current_setting('test.output')::uuid),'operation','allocations','date','2026-10-03','reference','QA rollback recovery','reason','NONLEGAL rollback qualification','allocations',jsonb_build_array(jsonb_build_object('employment_id',(SELECT employment_id FROM payroll.final_employees WHERE tenant_id=current_setting('test.tenant')::uuid AND output_id=current_setting('test.output')::uuid ORDER BY employment_id LIMIT 1),'amount','1.00')),'original',NULL,'confirmed','yes')::text,true);
SELECT set_config('test.attempt',gen_random_uuid()::text,true);
SELECT set_config('test.cancel_attempt',gen_random_uuid()::text,true);
SELECT set_config('test.before_events',(SELECT count(*)::text FROM payroll.payment_events WHERE tenant_id=current_setting('test.tenant')::uuid AND output_id=current_setting('test.output')::uuid),true);
SELECT set_config('test.before_receipts',(SELECT count(*)::text FROM payroll.command_receipts WHERE tenant_id=current_setting('test.tenant')::uuid AND actor_id=current_setting('test.actor')::uuid),true);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',current_setting('test.actor'),true);
SELECT lives_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.attempt')::uuid,current_setting('test.request')::jsonb)$$,'prepare persists original without payment');
SELECT lives_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.attempt')::uuid,current_setting('test.request')::jsonb)$$,'identical prepare replays');
SELECT throws_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.attempt')::uuid,jsonb_set(current_setting('test.request')::jsonb,'{reference}','"changed"'))$$,'PT409','payroll_attempt_conflict','same attempt cannot reinterpret reference');
SELECT throws_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,gen_random_uuid(),current_setting('test.request')::jsonb)$$,'55P03','payroll_payment_request_scope_busy','second pending request blocked');
SELECT is(public.payroll_payment_request_get(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid)->>'attempt',current_setting('test.attempt'),'reload discovers pending attempt without browser payload');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000099',true);
SELECT throws_ok($$SELECT public.payroll_payment_request_submit(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.attempt')::uuid)$$,'42501','payroll_forbidden','another actor cannot submit');
SELECT set_config('request.jwt.claim.sub',current_setting('test.actor'),true);
SELECT throws_ok($$SELECT public.payroll_payment_request_cancel(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,gen_random_uuid(),current_setting('test.attempt')::uuid)$$,'42501','payroll_forbidden','cancel requires exact output');
SELECT throws_ok($$SELECT public.payroll_payment_request_submit(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,gen_random_uuid(),current_setting('test.attempt')::uuid)$$,'42501','payroll_forbidden','same actor cannot replay into another output');
SELECT lives_ok($$SELECT public.payroll_payment_request_submit(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.attempt')::uuid)$$,'submit original persisted values');
SELECT lives_ok($$SELECT public.payroll_payment_request_submit(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.attempt')::uuid)$$,'response lost replay returns same receipt');
SELECT is(public.payroll_payment_request_get(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid),NULL::jsonb,'resolved request does not hide next payment form');
SELECT throws_ok($$SELECT public.payroll_payment_request_cancel(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.attempt')::uuid)$$,'23514','payroll_payment_request_committed','committed payment cannot be cancelled');
SELECT lives_ok($$SELECT public.payroll_payment_request_cancel(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.cancel_attempt')::uuid)$$,'missing prepare can be safely tombstoned');
SELECT lives_ok($$SELECT public.payroll_payment_request_cancel(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.cancel_attempt')::uuid)$$,'cancel response loss replays same tombstone');
SELECT throws_ok($$SELECT public.payroll_payment_request_submit(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.cancel_attempt')::uuid)$$,'23514','payroll_payment_request_cancelled','cancelled identity never submits');
SELECT throws_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.cancel_attempt')::uuid,current_setting('test.request')::jsonb)$$,'PT409','payroll_attempt_conflict','late prepare cannot bypass tombstone');
SELECT throws_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,gen_random_uuid(),jsonb_set(current_setting('test.request')::jsonb,'{date}','"-infinity"'))$$,'22023','payroll_payment_invalid','noncivil date refused before prepare');
RESET ROLE;
SELECT is((SELECT count(*) FROM payroll.payment_events WHERE tenant_id=current_setting('test.tenant')::uuid AND output_id=current_setting('test.output')::uuid),current_setting('test.before_events')::bigint+1,'one financial event across two submits');
SELECT is((SELECT count(*) FROM payroll.command_receipts WHERE tenant_id=current_setting('test.tenant')::uuid AND actor_id=current_setting('test.actor')::uuid),current_setting('test.before_receipts')::bigint+1,'one original command receipt');
SELECT is((SELECT request->>'reference' FROM payroll.payment_requests WHERE actor_id=current_setting('test.actor')::uuid AND attempt_key=current_setting('test.attempt')::uuid),'QA rollback recovery','stored original reference unchanged');
SELECT throws_ok($$UPDATE payroll.payment_requests SET request=jsonb_set(request,'{reference}','"overwritten"') WHERE actor_id=current_setting('test.actor')::uuid AND attempt_key=current_setting('test.attempt')::uuid$$,'55000','payroll_payment_request_immutable','database prevents overwriting original');
SELECT throws_ok($$UPDATE payroll.payment_requests SET state='pending',result=NULL,resolved_at=NULL WHERE actor_id=current_setting('test.actor')::uuid AND attempt_key=current_setting('test.attempt')::uuid$$,'55000','payroll_payment_request_immutable','committed request cannot reopen');
SELECT throws_ok($$DELETE FROM payroll.payment_requests WHERE actor_id=current_setting('test.actor')::uuid AND attempt_key=current_setting('test.attempt')::uuid$$,'55000','payroll_payment_request_immutable','request history cannot disappear');
SELECT set_config('test.legacy_attempt',gen_random_uuid()::text,true);
SELECT set_config('test.legacy_request',jsonb_set(current_setting('test.request')::jsonb,'{expected}',to_jsonb((SELECT revision FROM payroll.payment_heads WHERE tenant_id=current_setting('test.tenant')::uuid AND output_id=current_setting('test.output')::uuid)))::text,true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.payroll_record_payment(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,(current_setting('test.legacy_request')::jsonb->>'expected')::integer,'allocations','2026-10-03','QA rollback recovery','NONLEGAL rollback qualification',current_setting('test.legacy_request')::jsonb->'allocations',NULL,true,current_setting('test.legacy_attempt')::uuid)$$,'legacy command fixture commits only inside rollback');
SELECT throws_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.legacy_attempt')::uuid,jsonb_set(current_setting('test.legacy_request')::jsonb,'{reference}','"tampered legacy"'))$$,'PT409','payroll_attempt_conflict','tampered legacy cannot replace original receipt intent');
SELECT lives_ok($$SELECT public.payroll_payment_request_prepare(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.legacy_attempt')::uuid,current_setting('test.legacy_request')::jsonb)$$,'exact legacy request migrates to server');
SELECT lives_ok($$SELECT public.payroll_payment_request_submit(current_setting('test.tenant')::uuid,current_setting('test.employer')::uuid,current_setting('test.output')::uuid,current_setting('test.legacy_attempt')::uuid)$$,'legacy migration recovers original receipt');
RESET ROLE;
SELECT is((SELECT count(*) FROM payroll.payment_events WHERE tenant_id=current_setting('test.tenant')::uuid AND output_id=current_setting('test.output')::uuid),current_setting('test.before_events')::bigint+2,'legacy migration has no extra financial event');
SELECT * FROM finish();
ROLLBACK;
